CREATE OR REPLACE FUNCTION public.guard_barber_self_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.operation_settings%ROWTYPE; o public.barber_lunch_overrides%ROWTYPE; dur interval; BEGIN IF public.has_role(auth.uid(),'admin') OR auth.uid() IS NULL THEN RETURN NEW; END IF; IF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.team_role IS DISTINCT FROM OLD.team_role OR NEW.active IS DISTINCT FROM OLD.active OR NEW.approved_at IS DISTINCT FROM OLD.approved_at OR NEW.archived_at IS DISTINCT FROM OLD.archived_at OR NEW.service_ids IS DISTINCT FROM OLD.service_ids OR NEW.commission_service_pct IS DISTINCT FROM OLD.commission_service_pct OR NEW.commission_plan_pct IS DISTINCT FROM OLD.commission_plan_pct OR NEW.specialty IS DISTINCT FROM OLD.specialty OR NEW.sort_order IS DISTINCT FROM OLD.sort_order OR NEW.color IS DISTINCT FROM OLD.color THEN RAISE EXCEPTION 'Sem permissão para alterar função, status ou permissões.' USING ERRCODE='42501'; END IF; IF NEW.lunch_start IS NOT NULL AND NEW.lunch_start IS DISTINCT FROM OLD.lunch_start THEN SELECT * INTO s FROM public.operation_settings WHERE id=1; SELECT * INTO o FROM public.barber_lunch_overrides WHERE barber_id=NEW.id; IF o.barber_id IS NOT NULL THEN dur:=o.ends_time-o.starts_time; ELSE dur:=s.lunch_end-s.lunch_start; END IF; IF dur IS NULL THEN RAISE EXCEPTION 'A administração ainda não definiu o almoço.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.business_periods p WHERE NEW.lunch_start>=p.opens_at AND NEW.lunch_start+dur<=p.closes_at) THEN RAISE EXCEPTION 'O almoço precisa ficar dentro do horário de funcionamento.'; END IF; END IF; RETURN NEW; END $$;